    await playback.finishSplash(promise, 'Space')
    // 标题底部行 y=40(dy=30)、x=260 — 早跳过时仅靠补满才会是 0x44(否则是滚动 bitmap 像素)
    expect(fb.indices[40 * 320 + 260]).toBe(0x44)
